@import "@fontsource-variable/inter";

/* Light (faithful): white paper, #202020 ink, a mid grey for the quiet half of headlines and
   the big numbers, grey hairlines. No colour accent anywhere. */
:root {
  --background: oklch(1 0 0);
  --foreground: oklch(0.248 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.248 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.248 0 0);
  --primary: oklch(0.248 0 0);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.961 0 0);
  --secondary-foreground: oklch(0.248 0 0);
  --muted: oklch(0.938 0 0);
  --muted-foreground: oklch(0.65 0 0);
  --accent: oklch(0.961 0 0);
  --accent-foreground: oklch(0.248 0 0);
  --destructive: oklch(0.55 0.19 27);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.545 0 0);
  --input: oklch(0.545 0 0);
  --ring: oklch(0.248 0 0);
  --highlight: oklch(0 0 0);
  --highlight-foreground: oklch(1 0 0);
  --glow: oklch(0.88 0 0);
  --chart-1: oklch(0.248 0 0);
  --chart-2: oklch(0.45 0 0);
  --chart-3: oklch(0.65 0 0);
  --chart-4: oklch(0.8 0 0);
  --chart-5: oklch(0.9 0 0);
  --sidebar: oklch(0.985 0 0);
  --sidebar-foreground: oklch(0.248 0 0);
  --sidebar-primary: oklch(0.248 0 0);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.961 0 0);
  --sidebar-accent-foreground: oklch(0.248 0 0);
  --sidebar-border: oklch(0.545 0 0);
  --sidebar-ring: oklch(0.248 0 0);

  --typeface-body: "Inter Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Inter Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0rem;
  --page-width: 90rem;
  --page-gutter: 0.625rem;
  --section-y: 5.5rem;
}

@media (min-width: 48rem) {
  :root {
    --page-gutter: 1.25rem;
  }
}

@media (min-width: 64rem) {
  :root {
    --section-y: 10rem;
  }
}

/* Dark (sibling): charcoal paper, light-grey ink, the same mid grey and hairlines. */
.dark {
  --background: oklch(0.2 0 0);
  --foreground: oklch(0.94 0 0);
  --card: oklch(0.2 0 0);
  --card-foreground: oklch(0.94 0 0);
  --popover: oklch(0.248 0 0);
  --popover-foreground: oklch(0.94 0 0);
  --primary: oklch(0.94 0 0);
  --primary-foreground: oklch(0.2 0 0);
  --secondary: oklch(0.27 0 0);
  --secondary-foreground: oklch(0.94 0 0);
  --muted: oklch(0.29 0 0);
  --muted-foreground: oklch(0.62 0 0);
  --accent: oklch(0.27 0 0);
  --accent-foreground: oklch(0.94 0 0);
  --destructive: oklch(0.66 0.17 27);
  --destructive-foreground: oklch(0.94 0 0);
  --border: oklch(0.431 0 0);
  --input: oklch(0.431 0 0);
  --ring: oklch(0.94 0 0);
  --highlight: oklch(1 0 0);
  --highlight-foreground: oklch(0.2 0 0);
  --glow: oklch(0.36 0 0);
  --chart-1: oklch(0.94 0 0);
  --chart-2: oklch(0.78 0 0);
  --chart-3: oklch(0.62 0 0);
  --chart-4: oklch(0.45 0 0);
  --chart-5: oklch(0.33 0 0);
  --sidebar: oklch(0.22 0 0);
  --sidebar-foreground: oklch(0.94 0 0);
  --sidebar-primary: oklch(0.94 0 0);
  --sidebar-primary-foreground: oklch(0.2 0 0);
  --sidebar-accent: oklch(0.27 0 0);
  --sidebar-accent-foreground: oklch(0.94 0 0);
  --sidebar-border: oklch(0.431 0 0);
  --sidebar-ring: oklch(0.94 0 0);
}
